'use client';

import {cloneElement, isValidElement, useEffect, useEffectEvent, useLayoutEffect, useMemo, useState, useRef, type FormEvent, type ReactNode} from 'react';
import {ArrowDownLeft, ArrowUpRight, ArrowRight, Building2, Check, CheckCircle2, ChevronRight, Download, Link2, Package, Plus, Search, Trash2, Truck, Wallet, X, AlertCircle, Clock3, Pencil, Layers3, History} from 'lucide-react';
import {type Company, type Shipment, type Payment, type Treatment, type Workspace, type WorkspaceProps, money, uid, today} from '../../lib/types';
import {add, subtract, multiply, confirmedMargin, validMoney, quantityAdd, quantitySubtract, quantityCompare, compare, affectsCash, companyDeletionReason} from '../../lib/accounting';
import { AppSelect, AppDatePicker } from './controls';
import { AppCombobox } from './combobox';
import { RecordActions } from './record-actions';
import { Modal } from './modal';
import { useInfiniteList, InfiniteListFooter } from './infinite-list';
import { CompanyAccountDetails } from './company-account-details';
import { AdvanceApplicationModal } from './advance-application-modal';
import { companyAccountBalance, companyAccountSummary, companyBalanceLabel, economicCompanyBalances, availableCompanyAdvances, applyCompanyAdvance, shipmentAdvanceSummary, shipmentSettlementLabel, validateAdvanceApplications } from '@/lib/company-account';
import './records.css';
import './advance-payment.css';

const choices = (values: readonly string[]) => values.map(value=>({value,label:value}));
const sumMoney = (values: string[]) => values.reduce((total,value)=>add(total,value),'0.00');
const shiftMoney = (a: string, b: string, sign = 1) => sign===1?add(a,b):subtract(a,b);
const calculatedAmount = (weight:string,rate:string) => {try{return multiply(weight,rate)}catch{return ''}};
const dateLabel = (value: string) => value ? new Date(value+'T12:00:00').toLocaleDateString('en-GB', {day:'2-digit',month:'short',year:'numeric'}) : 'Date unresolved';
const currencyMark = (data:Workspace) => data.currency==='PKR'?'₨':data.currency;
const signedAccountMoney = (data:Workspace,id:string,economicBalance?:string) => {const balance=economicBalance===undefined?companyAccountBalance(data,id):subtract('0',economicBalance);return `${compare(balance,'0')>0?'+ ':compare(balance,'0')<0?'− ':''}${money(balance.replace(/^-/,'') ,2)}`;};
const companyName = (data: Workspace,id:string) => data.companies.find(c=>c.id===id)?.name || 'Unallocated';
const actorName = (data:Workspace,value?:string) => data.companies.find(c=>c.id===value)?.name||value||'';
const sourceEvidence = (data:Workspace,reference?:string) => {const batch=data.imports.find(b=>b.id===reference);return batch?.fileKey?<a href={`/api/files?key=${encodeURIComponent(batch.fileKey)}`} target="_blank" rel="noreferrer">{batch.name} <ArrowUpRight size={11}/></a>:reference};
const treatments: Treatment[] = ['Supplier settlement','Customer receipt','Payment on behalf','Supplier-agreed deduction','Capitalized landed cost','Operating expense','Advance','Owner drawing','Other adjustment'];
const statusClass = (status:string) => status==='Delivered'||status==='Allocated'||status==='Active'?'green':status==='Rejected'||status==='Inactive'?'red':status==='In transit'?'blue':'amber';
function Badge({children, tone}:{children:ReactNode;tone?:string}) {return <span className={`rv-badge ${tone||statusClass(String(children))}`}><i/>{children}</span>}
function exportCsv(name:string, headers:string[], rows:unknown[][]) {const csv=[headers,...rows].map(row=>row.map(v=>{const raw=String(v??'');const safe=/^[=+\-@\t\r]/.test(raw)&&! /^-?\d+(?:\.\d+)?$/.test(raw)?"'"+raw:raw;return '"'+safe.replaceAll('"','""')+'"'}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`hisabflow-${name}-${today()}.csv`;a.click();URL.revokeObjectURL(url)}
function useNewEvent(event: string, open:(event:Event)=>void) {useEffect(()=>{window.addEventListener(event,open);return()=>window.removeEventListener(event,open)},[event,open])}

function Empty({icon,title,description,action}:{icon:ReactNode;title:string;description:string;action?:ReactNode}) {return <div className="rv-empty">{icon}<h3>{title}</h3><p>{description}</p>{action}</div>}
function Toolbar({value,onChange,placeholder,children}:{value:string;onChange:(v:string)=>void;placeholder:string;children?:ReactNode}) {return <div className="rv-toolbar"><label className="rv-search"><Search size={16}/><input aria-label={placeholder} placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}/></label><div className="rv-toolbar-options">{children}</div></div>}
function ViewTitle({eyebrow,title,subtitle,children}:{eyebrow:string;title:string;subtitle:string;children?:ReactNode}) {return <div className="rv-view-heading"><div><span className="rv-eyebrow">{eyebrow}</span><h2>{title}</h2><p>{subtitle}</p></div><div className="rv-heading-actions">{children}</div></div>}
function Stat({title,value,note,icon}:{title:string;value:string;note:string;icon:ReactNode}) {return <div className="panel rv-stat"><div className="rv-stat-top"><span>{title}</span><span className="rv-stat-icon">{icon}</span></div><strong className={value.length>19?'rv-stat-value-long':value.length>14?'rv-stat-value-medium':undefined}>{value}</strong><span className="muted">{note}</span></div>}
function Field({label,children,className=''}:{label:string;children:ReactNode;className?:string}) {return <label className={`field rv-field ${className}`}><span>{label}</span>{isValidElement<{'aria-label'?:string}>(children)&&typeof children.type!=='symbol'?cloneElement(children,{'aria-label':children.props['aria-label']||label}):children}</label>}
function Details({rows}:{rows:[string,ReactNode][]}) {return <dl className="rv-details">{rows.map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v||'Not provided'}</dd></div>)}</dl>}
function MoneyValue({currency,amount}:{currency:string;amount:string}) {return <span className={`rv-money-value ${amount.length>18?'is-long':amount.length>14?'is-medium':''}`}><span>{currency}</span>{' '}<span className="rv-money-number">{amount}</span></span>}
function RecordCard({id,title,subtitle,amount,currency,sign,amountLabel='Amount',tone,icon,badge,fields,actions,onView}:{id:string;title:string;subtitle?:string;amount:string;currency:string;sign?:string;amountLabel?:string;tone?:string;icon?:ReactNode;badge?:ReactNode;fields:[string,ReactNode][];actions?:ReactNode;onView?:()=>void}) {
 const visibleFields=fields.filter(([,value])=>value!==undefined&&value!==null&&value!=='');
 return <article className="rv-record-card" data-record-id={id} aria-label={title}>
  <header className={`rv-record-card-header ${icon?'has-icon':''}`}>{icon&&<span className="rv-record-card-icon">{icon}</span>}<div className="rv-record-card-heading"><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div></header>
  <div className="rv-record-card-value"><div className="rv-card-value-heading"><span>{amountLabel}</span>{badge}</div><div className={`rv-record-card-amount ${tone||''}`}><span className="rv-card-currency">{sign?`${sign} ${currency}`:currency}</span>{' '}<span className={`hf-card-number ${amount.length>18?'is-long':amount.length>14?'is-medium':''}`}>{amount}</span></div></div>
  {!!visibleFields.length&&<dl className="rv-record-card-meta">{visibleFields.map(([label,value])=><div key={label} className={label==='Email'?'rv-card-field-wide':undefined}><dt>{label}</dt><dd>{value}</dd></div>)}</dl>}
  {(actions||onView)&&<footer className="rv-record-card-actions">{onView&&<button type="button" className="button button-secondary" onClick={onView}>View details<ArrowUpRight size={15}/></button>}{actions}</footer>}
 </article>;
}


export function CompaniesView({data,update,notify,saveState='saved',saveConflict=false,retrySave}:WorkspaceProps) {
 const [query,setQuery]=useState('');const [role,setRole]=useState('All companies');const [editing,setEditing]=useState<Company|null|undefined>(undefined);const [selected,setSelected]=useState<Company|null>(null);const [aliasApproved,setAliasApproved]=useState(false);const [advanceShipment,setAdvanceShipment]=useState<string|null>(null);
 const [deleting,setDeleting]=useState<Company|null>(null);const [deletionRequested,setDeletionRequested]=useState(false);const companiesHeading=useRef<HTMLHeadingElement>(null);const companyActionFocus=useRef<HTMLElement|null>(null);
 const deletionReason=deleting?companyDeletionReason(data,deleting.id):null;
 const editCompany=(company:Company,trigger?:HTMLElement|null)=>{if(trigger)companyActionFocus.current=trigger;setAliasApproved(false);setSelected(null);setEditing(company)};
 const closeDelete=()=>{if(deletionRequested&&saveState==='saving')return;setDeleting(null);setDeletionRequested(false)};
 const deleteCompany=()=>{
  if(!deleting||deletionRequested)return;
  const reason=companyDeletionReason(data,deleting.id);
  if(reason){notify(reason);return}
  if(!data.companies.some(company=>company.id===deleting.id)){closeDelete();return}
  setDeletionRequested(true);
  update({...data,companies:data.companies.filter(company=>company.id!==deleting.id)},'Company deleted',`${deleting.name} · ${deleting.id}`);
 };
 const acknowledgeDeletion=useEffectEvent(()=>{
  if(!deletionRequested||!deleting)return;
  if(saveConflict){setDeletionRequested(false);return}
  if(saveState==='saved'&&!data.companies.some(company=>company.id===deleting.id)){
   notify(`${deleting.name} deleted`);setDeleting(null);setDeletionRequested(false);
   requestAnimationFrame(()=>companiesHeading.current?.focus());
  }
 });
 // Server acknowledgment closes the local confirmation only after persistence succeeds.
 // eslint-disable-next-line react-hooks/set-state-in-effect
 useEffect(()=>{acknowledgeDeletion()},[data.companies,deleting,deletionRequested,saveConflict,saveState]);
 useNewEvent('hisab:new-company',()=>{companyActionFocus.current=document.activeElement as HTMLElement|null;setAliasApproved(false);setEditing(null)});
 const companies=data.companies.filter(c=>(role==='All companies'||c.role===role||c.role==='Both')&&`${c.name} ${c.contact} ${c.aliases.join(' ')}`.toLowerCase().includes(query.toLowerCase()));
 const companyList=useInfiniteList(companies,JSON.stringify([query,role]));
 const save=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const aliases=String(f.get('aliases')||'').split(',').map(a=>a.trim()).filter(Boolean);if(aliases.length&&!aliasApproved){notify('Confirm the aliases belong to this company before saving.');return}const name=String(f.get('name')).trim();if(!name){notify('Enter a company name.');return}if(!editing&&!validMoney(String(f.get('balance')||'0'),true)){notify('Enter an opening balance with at most two decimal places.');return}if(data.companies.some(c=>c.id!==editing?.id&&(c.name.trim().toLowerCase()===name.toLowerCase()||c.aliases.some(alias=>alias.trim().toLowerCase()===name.toLowerCase())))){notify('A company with this name already exists. Review its record first.');return}const company:Company={id:editing?.id||uid('CO'),name,role:String(f.get('role')) as Company['role'],contact:String(f.get('contact')),email:String(f.get('email')),aliases,balance:editing?.balance||subtract('0',String(f.get('balance')||'0')),status:String(f.get('status')||'Active') as Company['status']};update({...data,companies:editing?data.companies.map(c=>c.id===editing.id?company:c):[...data.companies,company]},editing?'Company updated':'Company added',`${company.name}${aliases.length?' · aliases explicitly reviewed':''}`);setEditing(undefined);setSelected(null);notify(`Saving ${company.name}…`)};
 const balances=useMemo(()=>economicCompanyBalances(data),[data]);
 const receivable=sumMoney([...balances.values()].filter(balance=>compare(balance,'0')>0));const payable=sumMoney([...balances.values()].filter(balance=>compare(balance,'0')<0).map(balance=>subtract('0',balance)));
 const companyAction=(kind:'payment'|'delivery',advance=false)=>{if(!selected)return;const supplier=selected.role==='Supplier';setSelected(null);window.dispatchEvent(new CustomEvent('hisab:company-action',{detail:{kind,companyId:selected.id,direction:kind==='delivery'?'Dispatch':supplier?'Paid':'Received',treatment:advance?'Advance':supplier?'Supplier settlement':'Customer receipt'}}));};
 return <div className="rv-view"><ViewTitle eyebrow="YOUR BUSINESS NETWORK" title="Good business starts with good relationships." subtitle="Customers, suppliers, and every balance in between."><button className="button button-primary" onClick={e=>{companyActionFocus.current=e.currentTarget;setAliasApproved(false);setEditing(null)}}><Plus size={17}/>Add company</button></ViewTitle><div className="rv-stats"><Stat title="Total companies" value={String(data.companies.length).padStart(2,'0')} note={`${data.companies.filter(c=>c.status==='Active').length} active relationships`} icon={<Building2 size={18}/>}/><Stat title="To receive" value={`${currencyMark(data)} ${money(receivable)}`} note="Amounts due from company accounts" icon={<ArrowDownLeft size={18}/>}/><Stat title="To pay" value={`${currencyMark(data)} ${money(payable)}`} note="Supplier balances and customer credits" icon={<ArrowUpRight size={18}/>}/></div><section className="panel rv-table-panel"><div className="rv-section-heading"><h3 ref={companiesHeading} tabIndex={-1}>All companies <span className="rv-count">{companies.length}</span></h3><button className="button button-secondary rv-small" onClick={()=>exportCsv('companies',['Name','Role','Balance','Status','Reviewed aliases'],companies.map(c=>[c.name,c.role,subtract('0',balances.get(c.id)||'0'),c.status,c.aliases.join('; ')]))}><Download size={15}/>Export</button></div><Toolbar value={query} onChange={setQuery} placeholder="Search companies or aliases..."><AppSelect aria-label="Company type" size="compact" value={role} onValueChange={setRole} options={choices(['All companies','Customer','Supplier','Both'])}/></Toolbar><div className="table-wrap hf-desktop-only"><table className="data-table rv-table"><thead><tr><th>Company</th><th>Relationship</th><th>Contact</th><th>Balance · {data.currency}</th><th>Status</th><th className="rv-company-actions-heading">Actions</th></tr></thead><tbody>{companyList.visibleItems.map((c,i)=><tr key={c.id} onClick={e=>{companyActionFocus.current=e.currentTarget;setSelected(c)}} tabIndex={0} onKeyDown={e=>{if(e.target===e.currentTarget&&e.key==='Enter'){companyActionFocus.current=e.currentTarget;setSelected(c)}}}><td><span className="rv-company-cell"><span className={`rv-company-avatar rv-color-${i%4}`}>{c.name.split(' ').map(w=>w[0]).slice(0,2).join('')}</span><span><b>{c.name}</b><small>{c.id}</small></span></span></td><td><span className="rv-role">{c.role}</span></td><td>{c.contact||<span className="muted">—</span>}</td><td><b className={compare(subtract('0',balances.get(c.id)||'0'),'0')>0?'rv-green':''}>{signedAccountMoney(data,c.id,balances.get(c.id))}</b><small>{companyBalanceLabel(data,c.id)}</small></td><td><Badge>{c.status}</Badge></td><td className="rv-company-actions-cell" onClick={e=>e.stopPropagation()} onKeyDown={e=>e.stopPropagation()}><RecordActions name={c.name} onView={trigger=>{companyActionFocus.current=trigger;setSelected(c)}} onEdit={trigger=>editCompany(c,trigger)} onDelete={trigger=>{companyActionFocus.current=trigger;setDeletionRequested(false);setDeleting(c)}}/></td></tr>)}</tbody></table></div><div className="hf-record-cards hf-mobile-only rv-record-cards" aria-label="Company cards">{companyList.visibleItems.map(c=><RecordCard key={c.id} id={c.id} title={c.name} subtitle={`${c.role} · ${c.id}`} amountLabel="Current balance" currency={currencyMark(data)} amount={money(subtract('0',balances.get(c.id)||'0').replace(/^-/,''),2)} sign={compare(subtract('0',balances.get(c.id)||'0'),'0')>0?'+':compare(subtract('0',balances.get(c.id)||'0'),'0')<0?'−':undefined} tone={compare(subtract('0',balances.get(c.id)||'0'),'0')>0?'rv-green':compare(subtract('0',balances.get(c.id)||'0'),'0')<0?'rv-account-due':''} icon={<Building2 size={19}/>} badge={<Badge>{c.status}</Badge>} fields={[["Balance",companyBalanceLabel(data,c.id)],["Contact",c.contact],["Email",c.email]]} onView={()=>{companyActionFocus.current=document.activeElement as HTMLElement|null;setSelected(c)}} actions={<RecordActions name={c.name} onView={trigger=>{companyActionFocus.current=trigger;setSelected(c)}} onEdit={trigger=>editCompany(c,trigger)} onDelete={trigger=>{companyActionFocus.current=trigger;setDeletionRequested(false);setDeleting(c)}}/>}/>)}</div>{!companies.length&&<Empty icon={<Building2 size={30}/>} title="No companies found" description="Add your first company or try a different search."/>}<InfiniteListFooter list={companyList} label="companies"/><div className="rv-table-footer"><span>All balances in {data.currency}</span></div></section>
 {editing!==undefined&&<Modal title={editing?'Edit company':'A new connection'} subtitle="Keep the accounting company separate from delivery and payment actors." onClose={()=>setEditing(undefined)} restoreFocusRef={companyActionFocus} footer={<div className="form-actions rv-form-actions"><button type="button" className="button button-secondary" onClick={()=>setEditing(undefined)}>Cancel</button><button className="button button-primary" type="submit"><Check size={17}/>Save company</button></div>} formProps={{onSubmit:save}}><div className="form-grid rv-form-grid"><Field label="Company name *"><input autoFocus name="name" required defaultValue={editing?.name} placeholder="e.g. Greenfield Industries"/></Field><Field label="Relationship *"><AppSelect name="role" defaultValue={editing?.role||'Customer'} options={choices(['Customer','Supplier','Both'])}/></Field><Field label="Contact person"><input name="contact" defaultValue={editing?.contact} placeholder="Contact name"/></Field><Field label="Email"><input name="email" type="email" defaultValue={editing?.email} placeholder="accounts@company.com"/></Field>{!editing&&<Field label={`Opening balance · ${data.currency}`}><input name="balance" type="number" inputMode="decimal" step="0.01" defaultValue="0"/><small>Negative = company owes you · Positive = company credit / you owe</small></Field>}<Field label="Status"><AppSelect name="status" defaultValue={editing?.status||'Active'} options={choices(['Active','Inactive'])}/></Field><Field label="Reviewed aliases · comma separated" className="rv-full"><input name="aliases" defaultValue={editing?.aliases.join(', ')} placeholder="Alternative names from source documents"/></Field><label className="rv-checkbox rv-full"><input type="checkbox" checked={aliasApproved} onChange={e=>setAliasApproved(e.target.checked)}/>I have checked that these aliases identify this company.</label></div></Modal>}
 {deleting&&<Modal title="Delete company" subtitle={deleting.name} onClose={closeDelete} restoreFocusRef={companyActionFocus} footer={<div className="form-actions rv-form-actions">
   <button type="button" className="button button-secondary" disabled={deletionRequested&&saveState==='saving'} onClick={closeDelete}>{deletionReason||deletionRequested?'Close':'Cancel'}</button>
   {deletionRequested&&saveState==='error'&&retrySave?<button type="button" className="button button-primary" onClick={retrySave}>Retry save</button>:<button type="button" className="button rv-delete-button" disabled={!!deletionReason||deletionRequested} onClick={deleteCompany}><Trash2 size={17}/>{deletionRequested?'Deleting…':'Delete company'}</button>}
  </div>}>
  {deletionRequested?<p className="rv-delete-description" role="status">{saveState==='error'?'The deletion has not been saved. Retry to finish removing this company.':'Deleting company…'}</p>:deletionReason?<div className="rv-delete-restriction"><AlertCircle size={20}/><p>{deletionReason} You can mark the company inactive from Edit.</p></div>:<p className="rv-delete-description">Delete <strong>{deleting.name}</strong>? This will permanently remove the company from your workspace.</p>}

 </Modal>}
 {selected&&<Modal title={selected.name} className="hf-company-account-modal" header={<><h2>Company account</h2><p className="muted">{selected.role} · {selected.id}</p></>} onClose={()=>setSelected(null)} restoreFocusRef={companyActionFocus} wide footer={<div className="rv-form-actions"><button className="button button-secondary" onClick={()=>editCompany(selected)}><Pencil size={15}/>Edit company</button></div>}><CompanyAccountDetails companyId={selected.id} data={data} onRecordPayment={advance=>companyAction('payment',advance)} onRecordSale={()=>companyAction('delivery')} onApplyAdvance={setAdvanceShipment} onReviewStatement={id=>{setSelected(null);window.dispatchEvent(new CustomEvent('hisab:review-import',{detail:{id}}));location.hash='Imports';}}/></Modal>}
 {advanceShipment&&<AdvanceApplicationModal shipmentId={advanceShipment} data={data} update={update} notify={notify} saveState={saveState} saveConflict={saveConflict} retrySave={retrySave} onClose={()=>setAdvanceShipment(null)}/>}
 </div>;
}

type CostAllocation = {shipmentId:string;weight:string;amount:string};
const normalized = (value:string) => value.trim().toLowerCase();
const quantityValid = (value:string) => /^\d+(?:\.\d{1,6})?$/.test(value);
const showQuantity = (value:string) => {if(!quantityValid(value))return value;const [whole,fraction='']=value.split('.');return whole+'.'+fraction.padEnd(3,'0').replace(/0+$/,'').padEnd(3,'0')};
function allocationAvailable(data:Workspace,source:Shipment,saleId:string):string {
 let reserved='0';
 for(const other of data.shipments.filter(s=>s.direction==='Dispatch'&&s.id!==saleId)) {
   for(const allocation of other.costAllocations||[])if(allocation.shipmentId===source.id&&quantityValid(allocation.weight))reserved=quantityAdd(reserved,allocation.weight);
   if(other.matchConfirmed&&other.matchedId===source.id&&source.matchConfirmed&&source.matchedId===other.id&&quantityValid(other.weight))reserved=quantityAdd(reserved,other.weight);
 }
 return quantitySubtract(source.weight||'0',reserved);
}
function CostAllocationEditor({sale,data,update,notify,onClose}:WorkspaceProps&{sale:Shipment;onClose:()=>void}) {
 const [picks,setPicks]=useState<CostAllocation[]>(sale.costAllocations?.map(a=>({...a}))||[]);
 const [evidence,setEvidence]=useState(sale.costAllocationEvidence||'');const [reviewed,setReviewed]=useState(false);
 const sources=data.shipments.filter(s=>s.direction==='Receipt'&&normalized(s.product)===normalized(sale.product)&&normalized(s.unit)===normalized(sale.unit)&&(!s.grade||!sale.grade||normalized(s.grade)===normalized(sale.grade))&&quantityValid(s.weight)&&validMoney(s.rate)&&Number(s.rate)>0);
 const assigned=picks.reduce((total,p)=>quantityValid(p.weight)?quantityAdd(total,p.weight):total,'0');
 const allocatedCost=sumMoney(picks.filter(p=>p.shipmentId&&quantityValid(p.weight)).map(p=>{const source=sources.find(s=>s.id===p.shipmentId);return source?calculatedAmount(p.weight,source.rate)||'0':'0'}));
 const full=quantityValid(sale.weight)&&quantityCompare(assigned,sale.weight)===0;
 const patch=(index:number,field:'shipmentId'|'weight',value:string)=>setPicks(prev=>prev.map((p,i)=>{if(i!==index)return p;const next={...p,[field]:value};const source=sources.find(s=>s.id===next.shipmentId);return {...next,amount:source&&quantityValid(next.weight)?calculatedAmount(next.weight,source.rate):''}}));
 const save=(confirm:boolean)=>{
  if(sale.matchConfirmed){notify('Unlink the confirmed single-source match before allocating multiple purchase sources.');return}
  if(!quantityValid(sale.weight)||quantityCompare(sale.weight,'0')<=0){notify('A known positive sale quantity is required to allocate purchase costs.');return}
  const used=new Set<string>();const allocations:CostAllocation[]=[];
  for(const pick of picks){const source=sources.find(s=>s.id===pick.shipmentId);if(!source||used.has(pick.shipmentId)||!quantityValid(pick.weight)||quantityCompare(pick.weight,'0')<=0){notify('Choose each purchase source once and enter a positive allocation quantity.');return}used.add(pick.shipmentId);const available=allocationAvailable(data,source,sale.id);if(quantityCompare(pick.weight,available)>0){notify(`${source.id} has only ${showQuantity(available)} ${source.unit} available after other allocations.`);return}allocations.push({...pick,amount:multiply(pick.weight,source.rate)})}
  if(quantityCompare(assigned,sale.weight)>0){notify('Allocated quantity cannot exceed the sale quantity.');return}
  if(confirm&&(!full||!reviewed||!evidence.trim())){notify('Confirm the relationship and accounting directions, provide evidence, and cover the complete sale quantity.');return}
  const next={...sale,costAllocations:allocations,costAllocationConfirmed:confirm,costAllocationEvidence:evidence.trim(),matchConfirmed:false,matchedId:undefined};
  update({...data,shipments:data.shipments.map(s=>s.id===sale.id?next:s)},confirm?'Purchase cost allocation confirmed':'Purchase cost allocation saved',`${sale.id} · ${allocations.length} purchase sources · ${showQuantity(assigned)} ${sale.unit} · ${confirm?'full coverage reviewed':'draft; margin unresolved'}`);
  notify(confirm?'Purchase costs confirmed across the selected sources':'Partial allocation saved. Trading margin remains unresolved.');onClose();
 };
 return <Modal title="Allocate purchase costs" subtitle={`${sale.id} · ${showQuantity(sale.weight)} ${sale.unit}`} onClose={onClose} wide footer={<div className="rv-form-actions"><button className="button button-secondary" onClick={()=>save(false)}>Save allocation draft</button><button className="button button-primary" disabled={!full||!reviewed||!evidence.trim()||!picks.length} onClick={()=>save(true)}><Check size={16}/>Confirm purchase costs</button></div>}>
  <h3 className="rv-detail-identity">{sale.product}</h3>
  <div className="rv-cost-overview"><div><span>Sale amount · {data.currency}</span><strong><MoneyValue currency={currencyMark(data)} amount={money(sale.amount,2)}/></strong></div><div><span>Allocated purchase costs</span><strong><MoneyValue currency={currencyMark(data)} amount={money(allocatedCost,2)}/></strong></div><div><span>Quantity coverage</span><strong>{showQuantity(assigned)} / {showQuantity(sale.weight)} <small>{sale.unit}</small></strong></div></div>
  <p className="rv-note"><Layers3 size={16}/>Choose one or more actual purchase receipts. Each source may supply several sales up to its available quantity. Only complete, reviewed cost coverage contributes to trading margin.</p>
  <div className="rv-cost-rows">{picks.map((pick,index)=>{const source=sources.find(s=>s.id===pick.shipmentId);const available=source?allocationAvailable(data,source,sale.id):'0';return <div className="rv-cost-row" key={index}><div className="rv-cost-row-top"><span>Purchase source {index+1}</span><button type="button" className="rv-icon-button" aria-label={`Remove purchase source ${index+1}`} onClick={()=>setPicks(picks.filter((_,i)=>i!==index))}><X size={14}/></button></div><div className="rv-cost-row-fields"><Field label="Purchase receipt *"><AppSelect aria-label={`Purchase source ${index+1}`} value={pick.shipmentId} onValueChange={value=>patch(index,'shipmentId',value)} options={[{value:'',label:'Select a purchase receipt'},...sources.filter(s=>s.id===pick.shipmentId||!picks.some(other=>other.shipmentId===s.id)).map(s=>({value:s.id,label:`${s.id} · ${companyName(data,s.companyId)} · ${s.vehicle||'No vehicle'}`}))]}/></Field><Field label={`Allocated quantity · ${sale.unit}`}><input aria-label={`Allocated quantity for purchase source ${index+1}`} type="number" inputMode="decimal" min="0.000001" step="0.000001" max={source?available:undefined} value={pick.weight} onChange={e=>patch(index,'weight',e.target.value)} placeholder="0.000"/></Field><Field label={`Allocated cost · ${data.currency}`}><input readOnly value={source&&quantityValid(pick.weight)?calculatedAmount(pick.weight,source.rate):''} placeholder="Calculated from purchase rate"/></Field></div>{source&&<div className="rv-cost-source-meta"><span>{dateLabel(source.date)} · {source.product} · {source.grade||'No grade recorded'}</span><span>Available: <b>{showQuantity(available)} {source.unit}</b> · Rate: {money(source.rate,2)}</span>{source.sourceRef&&<span>Source: {sourceEvidence(data,source.sourceRef)}</span>}</div>}</div>})}</div>
  {!sources.length&&<Empty icon={<Package size={28}/>} title="No compatible purchase sources" description="Record a receipt with the same product and unit, a known quantity, and a purchase rate. Missing costs stay unresolved."/>}
  <button type="button" className="button button-secondary rv-cost-add" disabled={!sources.length||picks.length>=sources.length} onClick={()=>setPicks([...picks,{shipmentId:'',weight:'',amount:''}])}><Plus size={16}/>Add purchase source</button>
  <Field label="Relationship evidence / review notes"><textarea rows={3} value={evidence} onChange={e=>setEvidence(e.target.value)} placeholder="Describe the source evidence connecting these purchases to this sale. Required before confirmation."/></Field>
  <label className="rv-checkbox rv-cost-confirm"><input type="checkbox" checked={reviewed} onChange={e=>setReviewed(e.target.checked)}/>I have reviewed the actual purchase/sale relationships and confirmed the accounting directions.</label>
  <p className={`rv-cost-coverage ${full?'complete':''}`}><span>{full?<CheckCircle2 size={16}/>:<AlertCircle size={16}/>}</span>{full?'Full quantity coverage. Ready for evidence-backed confirmation.':'Partial coverage. Save a draft; trading margin stays unresolved.'}</p>

 </Modal>;
}

export function DeliveriesView({data,update,notify,ownerId,saveState,saveConflict,retrySave}:WorkspaceProps) {
 const workspaceRef=useRef(data);useLayoutEffect(()=>{workspaceRef.current=data},[data]);
 const [query,setQuery]=useState('');const [direction,setDirection]=useState('All deliveries');const [party,setParty]=useState('All parties');const [form,setForm]=useState(false);const [selected,setSelected]=useState<Shipment|null>(null);const [matching,setMatching]=useState(false);const [confirm,setConfirm]=useState<string>('');const [weight,setWeight]=useState('');const [rate,setRate]=useState('');const [deliveryDirection,setDeliveryDirection]=useState<'Dispatch'|'Receipt'>('Dispatch');const [savingDelivery,setSavingDelivery]=useState(false);const [deliveryCompany,setDeliveryCompany]=useState('');const [useAdvance,setUseAdvance]=useState(false);const [advanceAmount,setAdvanceAmount]=useState('');const [advanceShipment,setAdvanceShipment]=useState<string|null>(null);const [manualAmount,setManualAmount]=useState('');const [costing,setCosting]=useState<Shipment|null>(null);const [unlinking,setUnlinking]=useState<Shipment|null>(null);const [unlinkReviewed,setUnlinkReviewed]=useState(false);
 const closeDelivery=()=>{if(savingDelivery)return;setForm(false);setWeight('');setRate('');setManualAmount('')};
 const openDelivery=()=>{setWeight('');setRate('');setManualAmount('');setDeliveryCompany('');setUseAdvance(false);setAdvanceAmount('');setForm(true)};
 useNewEvent('hisab:new-delivery',(event)=>{const detail=(event as CustomEvent).detail;openDelivery();if(detail?.direction==='Receipt'||detail?.direction==='Dispatch')setDeliveryDirection(detail.direction);if(typeof detail?.companyId==='string')setDeliveryCompany(detail.companyId);});
 const saleAmount=weight&&rate?calculatedAmount(weight,rate):manualAmount;
 const availableAdvance=availableCompanyAdvances(data,deliveryCompany,today()).reduce((total,source)=>add(total,source.available),'0.00');
 const maxAdvance=validMoney(saleAmount)&&compare(saleAmount,'0')>0?(compare(availableAdvance,saleAmount)<0?availableAdvance:saleAmount):'0.00';
 const rows=data.shipments.filter(s=>(direction==='All deliveries'||s.direction===direction||s.status===direction)&&(party==='All parties'||s.deliveryParty===party)&&`${s.id} ${s.vehicle} ${s.deliveryParty} ${s.product} ${companyName(data,s.companyId)}`.toLowerCase().includes(query.toLowerCase()));
 const deliveryList=useInfiniteList(rows,JSON.stringify([query,direction,party]));
 const matches=useMemo(()=>data.shipments.filter(a=>a.direction==='Receipt'&&!a.matchConfirmed&&!data.shipments.some(other=>other.direction==='Dispatch'&&other.costAllocations?.some(cost=>cost.shipmentId===a.id))).flatMap(a=>data.shipments.filter(b=>b.direction==='Dispatch'&&!b.matchConfirmed&&!b.costAllocations?.length&&a.vehicle&&a.vehicle.toLowerCase()===b.vehicle.toLowerCase()&&a.date===b.date&&quantityValid(a.weight)&&quantityValid(b.weight)&&quantityCompare(a.weight,b.weight)===0&&normalized(a.unit)===normalized(b.unit)&&(!a.grade||!b.grade||normalized(a.grade)===normalized(b.grade))&&a.product.toLowerCase()===b.product.toLowerCase()&&a.companyId!==b.companyId&&!!a.deliveryParty&&a.deliveryParty.trim().toLowerCase()===b.deliveryParty.trim().toLowerCase()).map(b=>({purchase:a,sale:b}))),[data.shipments]);
 const matchList=useInfiniteList(matches,`${matching}:`+matches.map(pair=>`${pair.purchase.id}:${pair.sale.id}`).join("|"));
 const save=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(savingDelivery)return;const f=new FormData(e.currentTarget);const val=(k:string)=>String(f.get(k)||'').trim();let total=val('amount');if(weight&&rate)total=calculatedAmount(weight,rate);if(!validMoney(total)||Number(total)<=0){notify('Enter a positive delivery amount.');return}const company=data.companies.find(c=>c.id===val('companyId'));if((val('direction')==='Receipt'&&company?.role==='Customer')||(val('direction')==='Dispatch'&&company?.role==='Supplier')){notify('Check the accounting company role before recording this direction.');return}let attachment='';const file=f.get('attachment');if(file instanceof File&&file.size){setSavingDelivery(true);try{const payload=new FormData();payload.set('file',file);const response=await fetch('/api/files',{method:'POST',headers:ownerId?{'X-Workspace-Owner':encodeURIComponent(ownerId)}:undefined,body:payload});const result=await response.json() as {error?:string;key:string};if(!response.ok)throw new Error(result.error||'Attachment upload failed');attachment=result.key}catch(error){notify(error instanceof Error?error.message:'Could not retain attachment');setSavingDelivery(false);return}setSavingDelivery(false)}const shipment:Shipment={attachment,id:uid('SHP'),direction:val('direction') as Shipment['direction'],companyId:val('companyId'),deliveryParty:val('deliveryParty'),date:val('date'),vehicle:val('vehicle'),product:val('product'),grade:val('grade'),weight:val('weight'),unit:val('unit'),rate:val('rate'),amount:total,status:val('status') as Shipment['status'],settlement:'Unsettled',relatedDocument:val('relatedDocument'),sourceRef:val('sourceRef'),transporter:val('transporter'),destination:val('destination'),notes:val('notes')};const current=workspaceRef.current;const companies=current.companies.map(c=>c.id===shipment.companyId?{...c,balance:shiftMoney(c.balance,total,shipment.direction==='Dispatch'?1:-1)}:c);let next:Workspace={...current,companies,shipments:[shipment,...current.shipments]};if(shipment.direction==='Dispatch'&&useAdvance){try{next=applyCompanyAdvance(next,shipment.id,advanceAmount,today())}catch(reason){notify(reason instanceof Error?reason.message:'Review the available advance.');return;}}update(next,'Delivery recorded',`${shipment.id} · ${shipment.direction} · ${shipment.vehicle||shipment.product}${useAdvance?` · advance applied ${advanceAmount} ${data.currency}`:''}`);setForm(false);setRate('');setWeight('');setManualAmount('');notify('Delivery recorded. Accounting settlement remains separate.')};
 const matchPair=(a:Shipment,b:Shipment)=>{if(confirm!==a.id+'-'+b.id){notify('Confirm the relationship and accounting directions before matching.');return}update({...data,shipments:data.shipments.map(s=>s.id===a.id?{...s,matchedId:b.id,matchConfirmed:true}:s.id===b.id?{...s,matchedId:a.id,matchConfirmed:true}:s)},'Shipment match confirmed',`${a.id} ↔ ${b.id} · directions and relationship reviewed`);setConfirm('');notify('Purchase and sale relationship confirmed')};
 const quantityByUnit=rows.reduce<Record<string,string>>((totals,row)=>{if(quantityValid(row.weight))totals[row.unit||'unit unresolved']=quantityAdd(totals[row.unit||'unit unresolved']||'0',row.weight);return totals},{});const quantitySummary=Object.entries(quantityByUnit).map(([unit,total])=>`${showQuantity(total)} ${unit}`).join(' · ');
 return <div className="rv-view"><ViewTitle eyebrow="FROM SOURCE TO DESTINATION" title="Every delivery. Every detail." subtitle="Follow your goods, one shipment at a time."><button className="button button-secondary" onClick={()=>setMatching(true)}><Link2 size={16}/>Review matches{matches.length>0&&<span className="rv-inline-count">{matches.length}</span>}</button><button className="button button-primary" onClick={openDelivery}><Plus size={17}/>Add delivery</button></ViewTitle><div className="rv-stats"><Stat title="Total deliveries" value={String(data.shipments.length).padStart(2,'0')} note={`${data.shipments.filter(s=>s.status==='Delivered').length} successfully delivered`} icon={<Truck size={18}/>}/><Stat title="In transit" value={String(data.shipments.filter(s=>s.status==='In transit').length).padStart(2,'0')} note="On their way to a destination" icon={<Package size={18}/>}/><Stat title="Awaiting match review" value={String(matches.length).padStart(2,'0')} note="Relationships need your confirmation" icon={<Link2 size={18}/>}/></div><section className="panel rv-table-panel"><div className="rv-section-heading"><h3>Shipment register <span className="rv-count">{rows.length}</span></h3><button className="button button-secondary rv-small" onClick={()=>exportCsv('deliveries',['ID','Direction','Date','Company','Delivery party','Vehicle','Product','Weight','Unit','Rate','Amount','Delivery status','Settlement','Source','Advance applied','Not covered by advance'],rows.map(s=>[s.id,s.direction,s.date,companyName(data,s.companyId),s.deliveryParty,s.vehicle,s.product,s.weight,s.unit,s.rate,s.amount,s.status,shipmentSettlementLabel(data,s.id),s.sourceRef,shipmentAdvanceSummary(data,s.id).applied,shipmentAdvanceSummary(data,s.id).outstanding]))}><Download size={15}/>Export</button></div><Toolbar value={query} onChange={setQuery} placeholder="Search vehicle, company, or shipment..."><AppSelect aria-label="Delivery party" size="compact" value={party} onValueChange={setParty} options={choices(['All parties',...new Set(data.shipments.map(s=>s.deliveryParty).filter(Boolean))])}/><AppSelect aria-label="Delivery filter" size="compact" value={direction} onValueChange={setDirection} options={choices(['All deliveries','Dispatch','Receipt','In transit','Rejected'])}/></Toolbar><div className="table-wrap hf-desktop-only"><table className="data-table rv-table"><thead><tr><th>Shipment / vehicle</th><th>Company / destination</th><th>Quantity</th><th>Amount · {data.currency}</th><th>Delivery status</th><th>Date</th><th/></tr></thead><tbody>{deliveryList.visibleItems.map(s=><tr key={s.id} onClick={()=>setSelected(s)} tabIndex={0} onKeyDown={e=>{if(e.key==='Enter')setSelected(s)}}><td><span className="rv-cell-with-icon"><span className={`rv-square-icon ${s.direction==='Dispatch'?'mint':'lilac'}`}><Truck size={17}/></span><span><b>{s.vehicle||s.id}</b><small>{s.id} · {s.direction}</small></span></span></td><td><b>{companyName(data,s.companyId)}</b><small>{s.deliveryParty||s.destination||'Destination not provided'}</small></td><td><b>{s.weight?Number(s.weight).toFixed(3):'—'} <span className="muted">{s.unit}</span></b><small>{s.product}</small></td><td><b>{money(s.amount,2)}</b><small>{s.matchConfirmed||s.costAllocationConfirmed?'Cost confirmed':s.direction==='Dispatch'?'Cost unresolved':'Purchase'}</small></td><td><Badge>{s.status}</Badge></td><td>{dateLabel(s.date)}</td><td><ChevronRight size={17}/></td></tr>)}</tbody></table></div><div className="hf-record-cards hf-mobile-only rv-record-cards" aria-label="Delivery cards">{deliveryList.visibleItems.map(s=><RecordCard key={s.id} id={s.id} title={s.vehicle||s.id} subtitle={`${s.direction} · ${s.id}`} amountLabel="Shipment amount" currency={currencyMark(data)} amount={money(s.amount,2)} icon={<Truck size={19}/>} badge={<Badge>{s.status}</Badge>} fields={[["Company",companyName(data,s.companyId)],["Delivery party",s.deliveryParty||s.destination],["Product",s.product],["Quantity",s.weight?`${showQuantity(s.weight)} ${s.unit}`:'Not recorded'],["Date",dateLabel(s.date)],["Purchase costs",s.matchConfirmed||s.costAllocationConfirmed?'Confirmed':s.direction==='Dispatch'?'Unresolved':'Purchase']]} onView={()=>setSelected(s)}/>)}</div>{!rows.length&&<Empty icon={<Truck size={30}/>} title="No deliveries here yet" description="Record a delivery or adjust your filters."/>}<InfiniteListFooter list={deliveryList} label="deliveries"/><div className="rv-table-footer"><span>Quantities: {quantitySummary||'No recorded quantities'}</span></div></section>
 {form&&<Modal title="Record a delivery" subtitle="One shipment, one unique reference. Vehicles can be reused." onClose={closeDelivery} wide footer={<div className="form-actions rv-form-actions"><button type="button" className="button button-secondary" disabled={savingDelivery} onClick={closeDelivery}>Cancel</button><button type="submit" disabled={savingDelivery} className="button button-primary"><Check size={17}/>{savingDelivery?'Retaining attachment…':'Save delivery'}</button></div>} formProps={{onSubmit:save}}><div className="form-grid rv-form-grid"><Field label="Direction *"><AppSelect name="direction" value={deliveryDirection} onValueChange={value=>{setDeliveryDirection(value as 'Dispatch'|'Receipt');setUseAdvance(false);setAdvanceAmount('');}} options={choices(['Dispatch','Receipt'])}/></Field><Field label="Accounting counterparty *"><AppSelect name="companyId" required value={deliveryCompany} onValueChange={value=>{setDeliveryCompany(value);setUseAdvance(false);setAdvanceAmount('');}} options={[{value:'',label:'Select a company',disabled:true},...data.companies.filter(c=>c.status==='Active').map(c=>({value:c.id,label:`${c.name} · ${c.role}`}))]}/></Field><Field label="Delivery recipient / party"><input name="deliveryParty" placeholder="Recipient, separate from counterparty"/></Field><Field label="Shipment date *"><AppDatePicker name="date" required defaultValue={today()}/></Field><Field label="Vehicle number"><input name="vehicle" placeholder="e.g. ABC-123"/></Field><Field label="Product *"><input name="product" required placeholder="e.g. Industrial material"/></Field><Field label="Grade"><input name="grade" placeholder="Optional product grade"/></Field><Field label="Delivery status"><AppSelect name="status" defaultValue="Delivered" options={choices(['Delivered','In transit','Pending','Rejected'])}/></Field><Field label="Weight / quantity"><input name="weight" type="number" inputMode="decimal" min="0" step="0.001" value={weight} onChange={e=>setWeight(e.target.value)} placeholder="0.000"/></Field><Field label="Unit"><AppSelect name="unit" defaultValue="t" options={[{value:'t',label:'Metric tonnes (t)'},{value:'kg',label:'Kilograms (kg)'},{value:'units',label:'Units'},{value:'',label:'Not applicable'}]}/></Field><Field label={`Rate per selected unit · ${data.currency}`}><input name="rate" type="number" inputMode="decimal" min="0" step="0.01" value={rate} onChange={e=>setRate(e.target.value)} placeholder="0.00"/></Field><Field label={`Amount * · ${data.currency}`}><input name="amount" type="number" inputMode="decimal" min="0.01" step="0.01" required readOnly={!!(weight&&rate)} value={weight&&rate?calculatedAmount(weight,rate):manualAmount} onChange={e=>setManualAmount(e.target.value)} placeholder="0.00"/></Field>{deliveryDirection==='Dispatch'&&deliveryCompany&&<section className="hf-delivery-advance" aria-label="Customer advance for this sale"><h3>Customer advance</h3><p>Available advance: <b>{data.currency} {money(availableAdvance,2)}</b></p><label className="rv-checkbox"><input type="checkbox" aria-label="Apply customer advance" checked={useAdvance} disabled={compare(maxAdvance,'0')<=0} onChange={event=>{setUseAdvance(event.target.checked);if(event.target.checked)setAdvanceAmount(maxAdvance);}}/>Use available advance for this sale</label>{useAdvance&&<Field label={`Advance to apply · ${data.currency}`}><input aria-label="Advance to apply" name="advanceAmount" required type="number" inputMode="decimal" step="0.01" min="0.01" max={maxAdvance} value={advanceAmount} onChange={event=>setAdvanceAmount(event.target.value)}/></Field>}<p>{compare(availableAdvance,'0')>0?'Applying advance uses money already received. No extra cash payment is recorded.':'No approved advance is available. This sale will be recorded on the company account.'}</p>{validMoney(saleAmount)&&<p>Company balance after this sale: <b>{data.currency} {money(subtract(companyAccountBalance(data,deliveryCompany),saleAmount),2)}</b></p>}</section>}<Field label="Related purchase / sale document"><input name="relatedDocument" placeholder="Original document reference, if known"/></Field><Field label="Source reference"><input name="sourceRef" placeholder="Source or attachment reference"/></Field><Field label="Transporter"><input name="transporter" placeholder="Optional transporter"/></Field><Field label="Delivery destination"><input name="destination" placeholder="Site, warehouse, or location"/></Field><Field label="Attachment" className="rv-full"><input name="attachment" type="file" accept=".pdf,.csv,.txt,.png,.jpg,.jpeg"/><small>PDF, image, or source evidence · up to 20 MB · private storage</small></Field><Field label="Exception notes" className="rv-full"><textarea name="notes" rows={2} placeholder="Quantity differences, rejection reason, or other evidence"/></Field></div><p className="rv-note"><AlertCircle size={15}/>Rejection is a delivery status. It does not automatically reverse the amount or settle the account.</p></Modal>}
 {selected&&<Modal title={selected.id} subtitle={`${selected.direction} · ${dateLabel(selected.date)}`} onClose={()=>setSelected(null)} wide footer={<div className="rv-form-actions">{selected.direction==='Dispatch'&&(selected.matchConfirmed?<button className="button button-secondary" onClick={()=>{setUnlinkReviewed(false);setUnlinking(selected);setSelected(null)}}><Link2 size={16}/>Review unlink</button>:<button className="button button-primary" onClick={()=>{setCosting(selected);setSelected(null)}}><Layers3 size={16}/>{selected.costAllocations?.length?'Review purchase costs':'Allocate purchase costs'}</button>)}<button className="button button-secondary" onClick={()=>{const current=data.shipments.find(s=>s.id===selected.id)!;const status=current.status==='In transit'?'Delivered':'In transit';update({...data,shipments:data.shipments.map(s=>s.id===current.id?{...s,status}:s)},'Delivery status updated',`${current.id} · ${status}`);setSelected({...current,status});notify(`Delivery marked ${status.toLowerCase()}`)}}>{selected.status==='In transit'?<CheckCircle2 size={16}/>:<Truck size={16}/>}Mark {selected.status==='In transit'?'delivered':'in transit'}</button></div>}><div className="rv-detail-summary"><div><span>Shipment amount · {data.currency}</span><strong><MoneyValue currency={currencyMark(data)} amount={money(selected.amount,2)}/></strong><small>{selected.weight||'No quantity'} {selected.unit} × {money(selected.rate,2)}</small></div><Badge>{selected.status}</Badge></div>{selected.direction==='Dispatch'&&<section className="hf-delivery-advance" aria-label="Order advance coverage"><h3>Advance coverage</h3><p>Advance applied: <b>{data.currency} {money(shipmentAdvanceSummary(data,selected.id).applied,2)}</b></p><p>Not covered by advance: <b>{data.currency} {money(shipmentAdvanceSummary(data,selected.id).outstanding,2)}</b></p><p>Other receipts are reflected in the company account balance.</p>{selected.status!=='Rejected'&&compare(shipmentAdvanceSummary(data,selected.id).outstanding,'0')>0&&compare(companyAccountSummary(data,selected.companyId).availableAdvance,'0')>0&&<button type="button" className="button button-secondary" onClick={()=>setAdvanceShipment(selected.id)}>Apply advance</button>}</section>}<Details rows={[["Accounting company",companyName(data,selected.companyId)],["Delivery party",selected.deliveryParty],["Vehicle",selected.vehicle],["Product / grade",[selected.product,selected.grade].filter(Boolean).join(' · ')],["Settlement",shipmentSettlementLabel(data,selected.id)],["Related document",selected.relatedDocument],["Transporter",selected.transporter],["Destination",selected.destination],["Source reference",sourceEvidence(data,selected.sourceRef)],["Attachment",selected.attachment?<a href={`/api/files?key=${encodeURIComponent(selected.attachment)}`} target="_blank" rel="noreferrer">View original attachment <ArrowUpRight size={11}/></a>:undefined],["Source location",selected.sourcePage?`Page ${selected.sourcePage} · Row ${selected.sourceRow}`:'Not imported'],["Confirmed matching shipment",selected.matchConfirmed?selected.matchedId:'Relationship unresolved'],["Purchase cost allocation",selected.costAllocations?.length?`${selected.costAllocations.length} sources · ${selected.costAllocationConfirmed?'Confirmed full coverage':'Draft; margin unresolved'}`:undefined],["Cost allocation evidence",selected.costAllocationEvidence],["Exception notes",selected.notes]]}/>{selected.status==='Rejected'&&<p className="rv-note"><AlertCircle size={16}/>The positive source amount is preserved. Accounting treatment requires separate review.</p>}</Modal>}
 {costing&&<CostAllocationEditor sale={costing} data={data} update={update} notify={notify} onClose={()=>setCosting(null)}/>}
 {unlinking&&<Modal title="Review unlinking this relationship" subtitle={`${unlinking.id} ↔ ${unlinking.matchedId}`} onClose={()=>setUnlinking(null)} footer={<div className="rv-form-actions"><button className="button button-secondary" onClick={()=>setUnlinking(null)}>Cancel</button><button className="button button-primary" disabled={!unlinkReviewed} onClick={()=>{if(!unlinkReviewed)return;const sale={...unlinking,matchedId:undefined,matchConfirmed:false};update({...data,shipments:data.shipments.map(s=>s.id===unlinking.id?sale:s.id===unlinking.matchedId&&s.matchedId===unlinking.id?{...s,matchedId:undefined,matchConfirmed:false}:s)},'Shipment relationship unlinked',`${unlinking.id} ↔ ${unlinking.matchedId} · explicitly reviewed`);setUnlinking(null);setSelected(sale);notify('Relationship unlinked. Purchase costs can now be reallocated.')}}><Check size={16}/>Unlink relationship</button></div>}><p className="rv-note"><AlertCircle size={16}/>This removes the confirmed purchase/sale relationship on both shipments. No amounts or delivery statuses change. Margin will remain unresolved until purchase costs are reviewed again.</p><label className="rv-checkbox"><input type="checkbox" checked={unlinkReviewed} onChange={e=>setUnlinkReviewed(e.target.checked)}/>I have reviewed the evidence and approve unlinking this purchase/sale relationship.</label></Modal>}
 {matching&&<Modal title="Review shipment relationships" subtitle="Matching clues suggest a relationship. You make the accounting decision." onClose={()=>setMatching(false)} wide footer={<div className="rv-form-actions"><button type="button" className="button button-secondary" onClick={()=>setMatching(false)}>Close</button></div>}>{matches.length?matchList.visibleItems.map(({purchase:a,sale:b})=><div className="rv-match-card" key={a.id+b.id}><div className="rv-match-heading"><span className="rv-square-icon mint"><Link2 size={18}/></span><div><h3>{a.vehicle} <span className="muted">· {Number(a.weight).toFixed(3)} {a.unit}</span></h3><p>{dateLabel(a.date)} · {a.product}</p></div><Badge tone="amber">Candidate</Badge></div><div className="rv-match-pair"><div><span>Receipt · potential purchase</span><b>{companyName(data,a.companyId)}</b><strong><MoneyValue currency={currencyMark(data)} amount={money(a.amount,2)}/></strong><small>{a.id} · {a.deliveryParty}</small>{a.sourceRef&&<small>{sourceEvidence(data,a.sourceRef)}</small>}</div><ArrowRight size={22}/><div><span>Dispatch · potential sale</span><b>{companyName(data,b.companyId)}</b><strong><MoneyValue currency={currencyMark(data)} amount={money(b.amount,2)}/></strong><small>{b.id} · {b.deliveryParty}</small>{b.sourceRef&&<small>{sourceEvidence(data,b.sourceRef)}</small>}</div></div><div className="rv-match-difference">Arithmetic amount difference <b><MoneyValue currency={currencyMark(data)} amount={money(shiftMoney(b.amount,a.amount,-1),2)}/></b></div><p className="rv-note">Vehicle, quantity, date, product, and delivery party match. Review the counterparties, delivery parties, and source evidence before confirming.</p><label className="rv-checkbox"><input type="checkbox" checked={confirm===a.id+'-'+b.id} onChange={e=>setConfirm(e.target.checked?a.id+'-'+b.id:'')}/>I confirmed this purchase/sale relationship and the accounting directions.</label><button className="button button-primary" disabled={confirm!==a.id+'-'+b.id} onClick={()=>matchPair(a,b)}><Check size={16}/>Confirm relationship</button></div>):<Empty icon={<Link2 size={30}/>} title="All relationships reviewed" description="New candidate matches appear when opposite-direction shipments share a vehicle, quantity, date, product, and delivery party."/>}<InfiniteListFooter list={matchList} label="relationships"/><p className="rv-note">Unmatched dispatch costs remain unresolved. HisabFlow does not create missing purchase costs.</p></Modal>}
 {advanceShipment&&<AdvanceApplicationModal shipmentId={advanceShipment} data={data} update={update} notify={notify} saveState={saveState} saveConflict={saveConflict} retrySave={retrySave} onClose={()=>setAdvanceShipment(null)}/>}
 </div>;
}

export function PaymentsView({data,update,notify}:WorkspaceProps) {
 const [query,setQuery]=useState('');const [filter,setFilter]=useState('All payments');const [paymentFrom,setPaymentFrom]=useState('');const [paymentTo,setPaymentTo]=useState('');const [editing,setEditing]=useState<Payment|null|undefined>(undefined);const [selected,setSelected]=useState<Payment|null>(null);const [allocated,setAllocated]=useState(true);const [paymentDirection,setPaymentDirection]=useState<'Received'|'Paid'>('Received');const [paymentContext,setPaymentContext]=useState<{companyId?:string;treatment?:Treatment}>({});
 useNewEvent('hisab:new-payment',(event)=>{const detail=(event as CustomEvent).detail;if(detail?.direction==='Paid'||detail?.direction==='Received')setPaymentDirection(detail.direction);setPaymentContext({companyId:typeof detail?.companyId==='string'?detail.companyId:undefined,treatment:treatments.includes(detail?.treatment)?detail.treatment:undefined});setEditing(null);setAllocated(true)});
 const rows=data.payments.filter(p=>(!paymentFrom||p.date>=paymentFrom)&&(!paymentTo||p.date<=paymentTo)&&(filter==='All payments'||p.direction===filter||p.status===filter)&&`${p.id} ${p.actor} ${p.reference} ${p.bankLabel} ${companyName(data,p.companyId)}`.toLowerCase().includes(query.toLowerCase()));
 const paymentList=useInfiniteList(rows,JSON.stringify([query,filter,paymentFrom,paymentTo]));
 const affectsBalance=(p:Payment)=>p.status==='Allocated'&&['Supplier settlement','Customer receipt','Payment on behalf','Supplier-agreed deduction'].includes(p.treatment);
 const save=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const val=(k:string)=>String(f.get(k)||'').trim();if(!validMoney(val('amount'))||Number(val('amount'))<=0){notify('Enter a positive amount with at most two decimal places.');return}if(allocated&&!val('companyId')){notify('Select the accounting company to approve allocation.');return}const payment:Payment={id:editing?.id||uid('PAY'),direction:val('direction') as Payment['direction'],date:val('date'),companyId:val('companyId'),actor:val('actor'),onBehalfOf:val('onBehalfOf'),amount:val('amount'),account:val('account'),bankLabel:val('bankLabel'),reference:val('reference'),treatment:val('treatment') as Treatment,status:allocated&&!/^Unassigned/i.test(val('account'))?'Allocated':'Needs review',notes:val('notes'),evidence:val('evidence'),sourceRef:editing?.sourceRef};const accountingCompany=data.companies.find(company=>company.id===payment.companyId);if(payment.treatment==='Supplier settlement'&&(payment.direction!=='Paid'||accountingCompany?.role==='Customer')){notify('Supplier settlements require money paid to a supplier.');return}if(payment.treatment==='Customer receipt'&&(payment.direction!=='Received'||accountingCompany?.role==='Supplier')){notify('Customer receipts require money received from a customer.');return}if(payment.treatment==='Payment on behalf'&&accountingCompany&&((payment.direction==='Paid'&&accountingCompany.role==='Customer')||(payment.direction==='Received'&&accountingCompany.role==='Supplier'))){notify('Review the accounting company and money direction for this payment on behalf.');return}if(payment.treatment==='Supplier-agreed deduction'&&payment.direction!=='Paid'){notify('A supplier deduction reduces a payable. Choose Paid as its direction.');return}if(payment.treatment==='Supplier-agreed deduction'&&!payment.evidence){notify('Add supporting evidence for a supplier-agreed deduction.');return}payment.balanceApplied=allocated&&['Supplier settlement','Customer receipt','Payment on behalf','Supplier-agreed deduction'].includes(payment.treatment);const companies=data.companies.map(c=>{let balance=c.balance;if(editing&&(editing.balanceApplied??affectsBalance(editing))&&editing.companyId===c.id)balance=shiftMoney(balance,editing.amount,editing.direction==='Received'?1:-1);if(payment.balanceApplied&&payment.companyId===c.id)balance=shiftMoney(balance,payment.amount,payment.direction==='Received'?-1:1);return {...c,balance}});const next={...data,companies,payments:editing?data.payments.map(p=>p.id===editing.id?payment:p):[payment,...data.payments]};const advanceErrors=validateAdvanceApplications(next,data);if(advanceErrors.length){notify(advanceErrors[0]);return;}update(next,editing?'Payment reviewed':'Payment recorded',`${payment.id} · ${payment.treatment} · ${payment.status}`);setEditing(undefined);notify(payment.status==='Allocated'?'Saving payment with deliberate allocation…':'Saving payment to the review queue…')};
 const cashPayments=data.payments.filter(affectsCash);
 return <div className="rv-view"><ViewTitle eyebrow="MONEY, WITH CONTEXT" title="A clearer picture of every payment." subtitle="Keep the actual payer, beneficiary, and accounting company connected."><button className="button button-primary" onClick={()=>{setPaymentContext({});setEditing(null);setAllocated(true)}}><Plus size={17}/>Record payment</button></ViewTitle><div className="rv-stats"><Stat title="Money received" value={`${currencyMark(data)} ${money(sumMoney(cashPayments.filter(p=>p.direction==='Received').map(p=>p.amount)))}`} note="Recorded cash and bank receipts" icon={<ArrowDownLeft size={18}/>}/><Stat title="Money paid" value={`${currencyMark(data)} ${money(sumMoney(cashPayments.filter(p=>p.direction==='Paid').map(p=>p.amount)))}`} note="Each cash movement counted once" icon={<ArrowUpRight size={18}/>}/><Stat title="Needs allocation review" value={String(data.payments.filter(p=>p.status==='Needs review').length).padStart(2,'0')} note="Not settled against a company yet" icon={<Clock3 size={18}/>}/></div><section className="panel rv-table-panel"><div className="rv-section-heading"><h3>Payment activity <span className="rv-count">{rows.length}</span></h3><button className="button button-secondary rv-small" onClick={()=>exportCsv('payments',['ID','Date','Direction','Accounting company','Actual payer or beneficiary','On behalf of','Amount','Own account','Raw bank label','Reference','Treatment','Allocation'],rows.map(p=>[p.id,p.date,p.direction,companyName(data,p.companyId),p.actor,p.onBehalfOf,p.amount,p.account,p.bankLabel,p.reference,p.treatment,p.status]))}><Download size={15}/>Export</button></div><Toolbar value={query} onChange={setQuery} placeholder="Search actor, company, or reference..."><AppSelect aria-label="Payment filter" size="compact" value={filter} onValueChange={setFilter} options={choices(['All payments','Received','Paid','Needs review','Allocated'])}/><label className="rv-date-field"><span>From</span><AppDatePicker aria-label="Payment from date" size="compact" value={paymentFrom} onValueChange={setPaymentFrom}/></label><label className="rv-date-field"><span>To</span><AppDatePicker aria-label="Payment to date" size="compact" value={paymentTo} onValueChange={setPaymentTo}/></label></Toolbar><div className="table-wrap hf-desktop-only"><table className="data-table rv-table"><thead><tr><th>Payment / company</th><th>Actual payer / beneficiary</th><th>Amount · {data.currency}</th><th>Treatment</th><th>Allocation</th><th>Date</th><th/></tr></thead><tbody>{paymentList.visibleItems.map(p=><tr key={p.id} onClick={()=>setSelected(p)} tabIndex={0} onKeyDown={e=>{if(e.key==='Enter')setSelected(p)}}><td><span className="rv-cell-with-icon"><span className={`rv-square-icon ${p.direction==='Received'?'mint':'peach'}`}>{p.direction==='Received'?<ArrowDownLeft size={18}/>:<ArrowUpRight size={18}/>}</span><span><b>{companyName(data,p.companyId)}</b><small>{p.id} · {p.direction}</small></span></span></td><td><b>{p.actor||'Unidentified'}</b><small>{p.onBehalfOf?`On behalf of ${actorName(data,p.onBehalfOf)}`:p.bankLabel||'Direct payment'}</small></td><td><b className={p.direction==='Received'?'rv-green':''}>{p.direction==='Received'?'+':'−'} {money(p.amount,2)}</b><small>{p.account}</small></td><td>{p.treatment}</td><td><Badge>{p.status}</Badge></td><td>{dateLabel(p.date)}</td><td><ChevronRight size={17}/></td></tr>)}</tbody></table></div><div className="hf-record-cards hf-mobile-only rv-record-cards" aria-label="Payment cards">{paymentList.visibleItems.map(p=><RecordCard key={p.id} id={p.id} title={companyName(data,p.companyId)} subtitle={`${p.direction} · ${p.id}`} amountLabel={p.direction==='Received'?'Money received':'Money paid'} currency={currencyMark(data)} sign={p.direction==='Received'?'+':'−'} amount={money(p.amount,2)} tone={p.direction==='Received'?'rv-green':''} icon={p.direction==='Received'?<ArrowDownLeft size={19}/>:<ArrowUpRight size={19}/>} badge={<Badge>{p.status}</Badge>} fields={[["Actual payer / beneficiary",p.actor],["Own account",p.account],["Treatment",p.treatment],["Date",dateLabel(p.date)],["Reference",p.reference],["On behalf of",actorName(data,p.onBehalfOf)]]} onView={()=>setSelected(p)}/>)}</div>{!rows.length&&<Empty icon={<Wallet size={30}/>} title="No payments found" description="Record a payment or adjust your search."/>}<InfiniteListFooter list={paymentList} label="payments"/><div className="rv-table-footer"><span>Payment references are preserved as entered</span></div></section>
 {editing!==undefined&&<Modal title={editing?'Review payment':'Record a payment'} subtitle="One movement, with clear ownership and allocation." onClose={()=>setEditing(undefined)} wide footer={<div className="form-actions rv-form-actions"><button type="button" className="button button-secondary" onClick={()=>setEditing(undefined)}>Cancel</button><button type="submit" className="button button-primary"><Check size={17}/>Save payment</button></div>} formProps={{onSubmit:save}}><div className="form-grid rv-form-grid"><Field label="Money movement *"><AppSelect name="direction" defaultValue={editing?.direction||paymentDirection} options={choices(['Received','Paid'])}/></Field><Field label="Effective date *"><AppDatePicker name="date" required defaultValue={editing?.date||today()}/></Field><Field label={`Amount * · ${data.currency}`}><input name="amount" required type="number" inputMode="decimal" min="0.01" step="0.01" defaultValue={editing?.amount} placeholder="0.00"/></Field><Field label="Accounting company"><AppSelect name="companyId" defaultValue={editing?.companyId||paymentContext.companyId||''} options={[{value:'',label:'Unresolved · review later'},...data.companies.map(c=>({value:c.id,label:c.name}))]}/></Field><Field label="Actual payer / beneficiary *"><input name="actor" required defaultValue={editing?.actor||data.companies.find(company=>company.id===paymentContext.companyId)?.name} placeholder="Who actually sent or received the funds?"/></Field><Field label="On behalf of"><input name="onBehalfOf" defaultValue={editing?.onBehalfOf} placeholder="Party represented by this payment"/></Field><Field label="My cash / bank account *"><AppCombobox name="account" required defaultValue={editing?.account||(paymentContext.companyId?'Business current':'Unassigned')} placeholder="Your own account" aria-label="My cash / bank account" options={['Business current','Petty cash','Non-cash adjustment','Unassigned']}/></Field><Field label="Source bank label"><input name="bankLabel" defaultValue={editing?.bankLabel} placeholder="As printed, e.g. UBL or MBL"/></Field><Field label="Transaction reference / TID"><input name="reference" defaultValue={editing?.reference} placeholder="Any text; leave blank if absent"/></Field><Field label="Reviewed accounting treatment *"><AppSelect required name="treatment" defaultValue={editing?.treatment||paymentContext.treatment||''} options={[{value:'',label:'Select treatment',disabled:true},...choices(treatments)]}/></Field><Field label="Supporting evidence"><input name="evidence" defaultValue={editing?.evidence} placeholder="Approval, document, or evidence reference"/></Field><Field label="Reason / notes"><input name="notes" defaultValue={editing?.notes} placeholder="Why this treatment applies"/></Field><label className="rv-checkbox rv-full"><input type="checkbox" checked={allocated} onChange={e=>setAllocated(e.target.checked)}/>I approve allocation to the selected accounting company.</label></div><p className="rv-note"><AlertCircle size={15}/>Third-party actors are preserved separately. A bank label is not automatically one of your bank accounts.</p></Modal>}
 {selected&&<Modal title={selected.id} subtitle={`${selected.direction} · ${dateLabel(selected.date)}`} onClose={()=>setSelected(null)} footer={<div className="rv-form-actions"><button className="button button-primary" onClick={()=>{setEditing(selected);setAllocated(selected.status==='Allocated'||selected.balanceApplied===true);setSelected(null)}}><Pencil size={16}/>Review allocation</button></div>}><div className="rv-detail-summary"><div><span>{selected.direction==='Received'?'Amount received':'Amount paid'} · {data.currency}</span><strong><MoneyValue currency={currencyMark(data)} amount={money(selected.amount,2)}/></strong></div><Badge>{selected.status}</Badge></div><Details rows={[["Accounting company",companyName(data,selected.companyId)],["Actual payer / beneficiary",selected.actor],["On behalf of",actorName(data,selected.onBehalfOf)],["My own account",selected.account],["Raw bank label",selected.bankLabel],["Reference / TID",selected.reference],["Accounting treatment",selected.treatment],["Supporting evidence",selected.evidence],["Reason / notes",selected.notes],["Original source",sourceEvidence(data,selected.sourceRef)]]}/></Modal>}
 </div>;
}

export function ReportsView({data,notify}:WorkspaceProps) {
 const [tab,setTab]=useState('Cash flow');const [query,setQuery]=useState('');const [from,setFrom]=useState('');const [to,setTo]=useState('');
 const inRange=(date:string)=>(!from||date>=from)&&(!to||date<=to);
 const payments=data.payments.filter(p=>inRange(p.date)&&affectsCash(p)&&`${p.actor} ${companyName(data,p.companyId)}`.toLowerCase().includes(query.toLowerCase()));
 const shipments=data.shipments.filter(s=>inRange(s.date)&&`${s.vehicle} ${s.deliveryParty} ${companyName(data,s.companyId)}`.toLowerCase().includes(query.toLowerCase()));
 const companies=data.companies.filter(c=>c.name.toLowerCase().includes(query.toLowerCase()));
 const audit=data.audit.filter(a=>inRange(a.at.slice(0,10))&&`${a.action} ${a.detail} ${a.actor}`.toLowerCase().includes(query.toLowerCase()));
 const margin=confirmedMargin({...data,shipments:data.shipments.filter(s=>s.direction==='Receipt'||shipments.some(selected=>selected.id===s.id))});
 const received=sumMoney(payments.filter(p=>p.direction==='Received').map(p=>p.amount));const paid=sumMoney(payments.filter(p=>p.direction==='Paid').map(p=>p.amount));
 const balances=useMemo(()=>economicCompanyBalances(data),[data]);
 const tabs=['Cash flow','Company balances','Truck-wise deliveries','Trading margin','Audit trail'];
 const exportReport=()=>{if(tab==='Cash flow')exportCsv('cash-flow',['Date','Payment','Direction','Company','Actor','Account','Amount'],payments.map(p=>[p.date,p.id,p.direction,companyName(data,p.companyId),p.actor,p.account,p.amount]));else if(tab==='Company balances')exportCsv('company-balances',['Company','Role','Account balance','Receivable','Payable'],companies.map(c=>[c.name,c.role,subtract('0',balances.get(c.id)||'0'),compare(balances.get(c.id)||'0','0')>0?balances.get(c.id):'0',compare(balances.get(c.id)||'0','0')<0?subtract('0',balances.get(c.id)||'0'):'0']));else if(tab==='Audit trail')exportCsv('audit',['Timestamp','Actor','Action','Detail','Source'],audit.map(a=>[a.at,a.actor,a.action,a.detail,a.sourceRef]));else exportCsv(tab==='Trading margin'?'trading-margin':'truck-wise',['Shipment','Date','Vehicle','Company','Delivery party','Product','Weight','Unit','Amount','Matched ID','Relationship confirmed','Purchase cost allocations','Cost allocation confirmed','Cost evidence'],shipments.map(s=>[s.id,s.date,s.vehicle,companyName(data,s.companyId),s.deliveryParty,s.product,s.weight,s.unit,s.amount,s.matchedId,!!s.matchConfirmed,(s.costAllocations||[]).map(a=>`${a.shipmentId}: ${a.weight} ${s.unit} / ${a.amount}`).join('; '),!!s.costAllocationConfirmed,s.costAllocationEvidence]));notify('Report exported')};
 const reportKey=JSON.stringify([tab,query,from,to]);
 const paymentList=useInfiniteList(payments,reportKey);
 const companyList=useInfiniteList(companies,reportKey);
 const shipmentList=useInfiniteList(shipments,reportKey);
 const auditList=useInfiniteList(audit,reportKey);
 return <div className="rv-view">
  <ViewTitle eyebrow="SEE THE BIGGER PICTURE" title="Numbers you can stand behind." subtitle="Clear reports, confirmed margins, and the evidence behind every entry."><button className="button button-primary" onClick={exportReport}><Download size={16}/>Export report</button></ViewTitle>
  <div className="rv-stats"><Stat title="Net cash movement" value={`${currencyMark(data)} ${money(shiftMoney(received,paid,-1))}`} note="Money received less money paid" icon={<Wallet size={18}/>}/><Stat title="Confirmed trading margin" value={`${currencyMark(data)} ${money(margin.amount,2)}`} note="Confirmed purchase / sale relationships only" icon={<Layers3 size={18}/>}/><Stat title="Costs unresolved" value={String(margin.unresolved).padStart(2,'0')} note="Dispatches excluded from trading margin" icon={<AlertCircle size={18}/>}/></div>
  <section className="panel rv-table-panel">
   <div className="rv-report-tabs">{tabs.map(t=><button key={t} onClick={()=>setTab(t)} className={tab===t?'active':''}>{t}</button>)}</div>
   <Toolbar value={query} onChange={setQuery} placeholder={tab==='Audit trail'?'Search actions, people, or source...':'Search this report...'}><label className="rv-date-field"><span>From</span><AppDatePicker aria-label="From date" size="compact" value={from} onValueChange={setFrom}/></label><label className="rv-date-field"><span>To</span><AppDatePicker aria-label="To date" size="compact" value={to} onValueChange={setTo}/></label></Toolbar>
   {tab==='Cash flow'&&<>
    <div className="rv-report-summary"><div><span>Money received</span><strong className="rv-green"><MoneyValue currency={currencyMark(data)} amount={money(received,2)}/></strong></div><div><span>Money paid</span><strong><MoneyValue currency={currencyMark(data)} amount={money(paid,2)}/></strong></div><div><span>Net movement</span><strong><MoneyValue currency={currencyMark(data)} amount={money(shiftMoney(received,paid,-1),2)}/></strong></div></div>
    <div className="table-wrap hf-desktop-only"><table className="data-table rv-table"><thead><tr><th>Date</th><th>Company / actor</th><th>Own account</th><th>Direction</th><th>Amount · {data.currency}</th></tr></thead><tbody>{paymentList.visibleItems.map(p=><tr key={p.id}><td>{dateLabel(p.date)}</td><td><b>{companyName(data,p.companyId)}</b><small>{p.actor}</small></td><td>{p.account}</td><td><Badge tone={p.direction==='Received'?'green':'neutral'}>{p.direction}</Badge></td><td><b>{p.direction==='Received'?'+':'−'} {money(p.amount,2)}</b></td></tr>)}</tbody></table></div>
    <div className="hf-record-cards hf-mobile-only rv-record-cards" aria-label="Cash flow cards">{paymentList.visibleItems.map(p=><RecordCard key={p.id} id={p.id} title={companyName(data,p.companyId)} subtitle={p.actor} amountLabel={p.direction==='Received'?'Money received':'Money paid'} currency={currencyMark(data)} sign={p.direction==='Received'?'+':'−'} amount={money(p.amount,2)} tone={p.direction==='Received'?'rv-green':''} badge={<Badge tone={p.direction==='Received'?'green':'neutral'}>{p.direction}</Badge>} fields={[["Date",dateLabel(p.date)],["Own account",p.account],["Reference",p.reference],["Payment",p.id]]}/>)}</div>
    {!payments.length&&<Empty icon={<Wallet size={28}/>} title="No cash movements found" description="Adjust your search or date range to find recorded movements."/>}
    <InfiniteListFooter list={paymentList} label="cash movements"/>
    <p className="rv-note">Cash flow reflects allocated movements with a confirmed own account. Unassigned movements and noncash adjustments are excluded.</p>
   </>}
   {tab==='Company balances'&&<>
    <div className="table-wrap hf-desktop-only"><table className="data-table rv-table"><thead><tr><th>Company</th><th>Relationship</th><th>Account balance · {data.currency}</th><th>To receive · {data.currency}</th><th>To pay · {data.currency}</th><th>Status</th></tr></thead><tbody>{companyList.visibleItems.map(c=><tr key={c.id}><td><b>{c.name}</b></td><td>{c.role}</td><td><b>{signedAccountMoney(data,c.id,balances.get(c.id))}</b><small>{companyBalanceLabel(data,c.id)}</small></td><td className="rv-green">{compare(balances.get(c.id)||'0','0')>0?money(balances.get(c.id)||'0',2):'—'}</td><td>{compare(balances.get(c.id)||'0','0')<0?money(subtract('0',balances.get(c.id)||'0'),2):'—'}</td><td><Badge>{c.status}</Badge></td></tr>)}</tbody></table></div>
    <div className="hf-record-cards hf-mobile-only rv-record-cards" aria-label="Company balance cards">{companyList.visibleItems.map(c=><RecordCard key={c.id} id={c.id} title={c.name} subtitle={c.role} amountLabel="Current balance" currency={currencyMark(data)} amount={money(subtract('0',balances.get(c.id)||'0').replace(/^-/,''),2)} sign={compare(subtract('0',balances.get(c.id)||'0'),'0')>0?'+':compare(subtract('0',balances.get(c.id)||'0'),'0')<0?'−':undefined} tone={compare(subtract('0',balances.get(c.id)||'0'),'0')>0?'rv-green':compare(subtract('0',balances.get(c.id)||'0'),'0')<0?'rv-account-due':''} badge={<Badge>{c.status}</Badge>} fields={[["Balance",companyBalanceLabel(data,c.id)],["Company reference",c.id]]}/>)}</div>
    {!companies.length&&<Empty icon={<Building2 size={28}/>} title="No company balances found" description="Adjust your search to find a company."/>}
    <InfiniteListFooter list={companyList} label="company balances"/>
    <p className="rv-note">Account balances include approved advance credits and recorded opening balances. Negative means the company owes you; positive means company credit or an amount you owe. These amounts are not marked overdue without known due dates.</p>
   </>}
   {(tab==='Truck-wise deliveries'||tab==='Trading margin')&&<>
    <div className="table-wrap hf-desktop-only"><table className="data-table rv-table"><thead><tr><th>Vehicle / shipment</th><th>Date</th><th>Delivery party</th><th>Quantity</th><th>{tab==='Trading margin'?'Match status':'Direction'}</th><th>Amount · {data.currency}</th></tr></thead><tbody>{shipmentList.visibleItems.map(s=><tr key={s.id}><td><b>{s.vehicle||'No vehicle'}</b><small>{s.id}</small></td><td>{dateLabel(s.date)}</td><td>{s.deliveryParty||'Not provided'}</td><td>{s.weight?showQuantity(s.weight):'—'} {s.unit}</td><td>{tab==='Trading margin'?<Badge tone={s.matchConfirmed||s.costAllocationConfirmed?'green':'amber'}>{s.matchConfirmed||s.costAllocationConfirmed?'Confirmed':s.direction==='Dispatch'?'Cost unresolved':'Unmatched'}</Badge>:s.direction}</td><td><b>{money(s.amount,2)}</b></td></tr>)}</tbody></table></div>
    <div className="hf-record-cards hf-mobile-only rv-record-cards" aria-label={`${tab} cards`}>{shipmentList.visibleItems.map(s=><RecordCard key={s.id} id={s.id} title={s.vehicle||s.id} subtitle={companyName(data,s.companyId)} amountLabel="Shipment amount" currency={currencyMark(data)} amount={money(s.amount,2)} badge={tab==='Trading margin'?<Badge tone={s.matchConfirmed||s.costAllocationConfirmed?'green':'amber'}>{s.matchConfirmed||s.costAllocationConfirmed?'Confirmed':s.direction==='Dispatch'?'Cost unresolved':'Unmatched'}</Badge>:<Badge tone={s.direction==='Dispatch'?'green':'neutral'}>{s.direction}</Badge>} fields={[["Date",dateLabel(s.date)],["Delivery party",s.deliveryParty],["Quantity",s.weight?`${showQuantity(s.weight)} ${s.unit}`:'Not recorded'],["Product",s.product],["Shipment",s.id]]}/>)}</div>
    {!shipments.length&&<Empty icon={<Truck size={28}/>} title="No deliveries found" description="Adjust your search or date range to find a delivery."/>}
    <InfiniteListFooter list={shipmentList} label={tab==='Trading margin'?'margin records':'deliveries'}/>
    <p className="rv-note"><AlertCircle size={15}/>{tab==='Trading margin'?'Only reviewed relationships with confirmed accounting directions contribute to trading margin. This figure excludes unallocated overhead and is not net profit.':'Vehicles can occur on several shipments. Every source row keeps a separate shipment reference and quantity.'}</p>
   </>}
   {tab==='Audit trail'&&<>
    <div className="rv-audit-list">{audit.length?auditList.visibleItems.map(a=><article className="rv-audit-row" data-record-id={a.id} key={a.id}><span className="rv-activity-icon"><History size={17}/></span><div><b>{a.action}</b><p>{a.detail}</p><small>{a.actor} · {new Date(a.at).toLocaleString('en-GB',{timeZone:'Asia/Karachi'})}{a.sourceRef&&<> · Source: {sourceEvidence(data,a.sourceRef)}</>}</small></div><CheckCircle2 size={17}/></article>):<Empty icon={<History size={30}/>} title="A clean slate" description="Your next recorded action will appear here with its time and reviewer."/>}</div>
    <InfiniteListFooter list={auditList} label="audit entries"/>
    <p className="rv-note">Audit entries preserve who performed each reviewed action and link imported records to their source batch.</p>
   </>}
  </section>
 </div>;
}
